update public.products set translations = jsonb_build_object('ar', $ar${"name":"كرة إطفاء الحريق GFO ‏1.3 كغ","product_type":"كرة إطفاء حريق","weight":"1.3 كغ","short_description":"كرة سلامة تلقائية متعددة الاستخدامات، مثالية للمنازل والمطابخ والمناطق المعرضة لخطر الحريق.","overview":"كرة إطفاء الحريق GFO بوزن 1.3 كغ حل تلقائي للسلامة من الحرائق، مناسب للمنازل والمكاتب والمطابخ والمحلات والمناطق المعرضة لخطر الحريق. يمكن وضعها أو تثبيتها في الأماكن التي تحتاج إلى استجابة سريعة وتلقائية للحريق.","key_features":["تتفعل تلقائيًا عند ملامسة اللهب","تدعم الإخماد السريع للحريق","خفيفة الوزن وسهلة التركيب","مناسبة للأماكن الداخلية وبعض الأماكن الخارجية","لا تحتاج إلى تشغيل يدوي","عمر افتراضي 5 سنوات","تصميم غير سام وصديق للبيئة"],"specifications":{"نوع المنتج":"كرة إطفاء حريق","العلامة التجارية":"GFO","الوزن":"1.3 كغ","العمر الافتراضي":"5 سنوات","طريقة التفعيل":"عند ملامسة اللهب","الاستخدام":"إخماد تلقائي للحريق","الكمية":"وحدة واحدة"},"best_for":["المنازل","المكاتب","المطابخ","المحلات","المستودعات الصغيرة","المناطق الكهربائية"],"safety_notes":["مصمم لدعم إخماد الحرائق","يوفر استجابة تلقائية للحريق","يساعد على الحد من انتشار الحريق","مناسب كإجراء سلامة إضافي","استشر فريق SAMS لتحديد أفضل أماكن التركيب"],"usage_areas":["المنازل","المكاتب","المطابخ","المستودعات","المحلات"]}$ar$::jsonb) where slug = $ar$gfo-fire-ball-extinguisher-1-3-kg$ar$ and translations = '{}'::jsonb;
