update public.faqs set translations = jsonb_build_object('ar', $ar${"question":"ما مدى فعالية كرات إطفاء الحريق؟","answer":"صُممت كرات إطفاء الحريق لتوفير استجابة تلقائية لمكافحة الحريق. تتفعل عند ملامستها للهب، مما يجعلها إجراء سلامة إضافيًا فعالًا في المناطق عالية الخطورة."}$ar$::jsonb) where question = $ar$What is the effectiveness of fire balls?$ar$ and translations = '{}'::jsonb;
update public.faqs set translations = jsonb_build_object('ar', $ar${"question":"كيف تعمل كرة إطفاء الحريق؟","answer":"صُممت كرة إطفاء الحريق لإخماد الحريق بسرعة بعد ملامسة اللهب. عندما يلامس اللهب الكرة، يتفعل الصمام وتنطلق بودرة الإطفاء خلال ثوانٍ."}$ar$::jsonb) where question = $ar$How effective is a fire extinguisher ball?$ar$ and translations = '{}'::jsonb;
update public.faqs set translations = jsonb_build_object('ar', $ar${"question":"ما هي كرة إطفاء الحريق؟","answer":"كرة إطفاء الحريق جهاز إخماد كروي الشكل يُستخدم في حالات الحريق الطارئة. تعمل بطريقة مشابهة لطفايات الحريق التقليدية، لكنها مصممة للتفعيل التلقائي وسهولة التركيب."}$ar$::jsonb) where question = $ar$What is a fire ball extinguisher?$ar$ and translations = '{}'::jsonb;
update public.faqs set translations = jsonb_build_object('ar', $ar${"question":"هل يحتاج المنتج إلى تدريب؟","answer":"لا يحتاج إلى أي تدريب خاص. صُمم المنتج ليكون سهل الاستخدام ويتفعل تلقائيًا، ويمكن لأي شخص وضعه في مكانه أو رميه على الحريق في حالات الطوارئ."}$ar$::jsonb) where question = $ar$Does the product require training?$ar$ and translations = '{}'::jsonb;
update public.faqs set translations = jsonb_build_object('ar', $ar${"question":"أين يمكن وضعه؟","answer":"يمكن وضعه قرب المطابخ ولوحات الكهرباء وفي المركبات والمستودعات والمصانع وغرف الخوادم والمكاتب والمنازل وغيرها من الأماكن المعرضة لخطر الحريق."}$ar$::jsonb) where question = $ar$Where can it be placed?$ar$ and translations = '{}'::jsonb;
update public.faqs set translations = jsonb_build_object('ar', $ar${"question":"ما هو العمر الافتراضي للمنتج؟","answer":"العمر الافتراضي لكرات الإطفاء التلقائية والمزهريات الديكورية هو 5 سنوات، ولا تحتاج إلى صيانة أو إعادة تعبئة طوال هذه المدة."}$ar$::jsonb) where question = $ar$How long is the product life?$ar$ and translations = '{}'::jsonb;
update public.faqs set translations = jsonb_build_object('ar', $ar${"question":"هل يمكن استخدامه في المركبات؟","answer":"نعم، يُنصح بالكرة الصغيرة بوزن 400 غرام للمركبات وحجرات المحرك وصناديق السيارات لخفة وزنها وسهولة حملها."}$ar$::jsonb) where question = $ar$Can it be used in vehicles?$ar$ and translations = '{}'::jsonb;
update public.faqs set translations = jsonb_build_object('ar', $ar${"question":"هل يمكن استخدامه قرب لوحات الكهرباء؟","answer":"نعم، وضعها داخل لوحات الكهرباء أو فوقها مباشرة فعال جدًا، إذ تُخمد حرائق الكهرباء تلقائيًا من مصدرها قبل أن تنتشر."}$ar$::jsonb) where question = $ar$Can it be used near electrical panels?$ar$ and translations = '{}'::jsonb;

