update public.testimonials set translations = jsonb_build_object('ar', $ar${"name":"أشوتوش راي","position":"رئيس المرافق","company":"Industrial Hub Sohar","message":"فعالية أجهزة الإخماد من SAMS مبهرة. تمنحنا راحة البال لأننا نعلم أننا محميون في حالات الطوارئ."}$ar$::jsonb) where name = $ar$Ashutosh Rai$ar$ and translations = '{}'::jsonb;
